'use strict';
let voiceTakePreviewId=null;
const synthBeforeTakes=synthesizeOfflineVoice;synthesizeOfflineVoice=async function(){const voice=await synthBeforeTakes();voiceTakePreviewId=null;$('offlineVoiceAudio').src=voice.src;$('offlineVoiceAudio').hidden=false;return voice};
$('offlineVoiceAudio').after(Object.assign(document.createElement('details'),{id:'voiceTakesPanel',innerHTML:'<summary>Compare voice takes</summary><p class="note">Try another voice, pace or style, preview it, then save a take. Auditioning keeps the current dialogue unchanged. Use a take to replace the line’s voice and refresh lip-sync.</p><div class="rig-tools"><input id="voiceTakeName" maxlength="80" placeholder="Take name" aria-label="Voice take name"><button id="saveVoiceTake">Save preview as take</button></div><div id="voiceTakeList" class="ease-card-list"></div>'}));
function voiceTakeContext(){const c=offlineVoiceContext;if(!c||project!==c.project||current()!==c.scene||!storyLines(current()).includes(c.line))throw Error('Reopen this dialogue line first.');return c}
function validVoiceTake(t){return t&&typeof t.id==='string'&&t.id.length<=160&&typeof t.name==='string'&&t.name.length<=80&&typeof t.src==='string'&&/^data:audio\/(?:wav|wave|x-wav);base64,/.test(t.src)&&Number.isFinite(t.sourceDuration)&&t.sourceDuration>.05&&t.request&&typeof t.request.text==='string'&&t.request.text.length>0&&typeof t.request.voice==='string'&&t.request.voice.length<=100&&Number.isFinite(t.request.speed)&&t.request.speed>=.6&&t.request.speed<=1.6&&['natural','narrator','bright','gentle','serious'].includes(t.request.delivery)}
function rememberVoiceTake(line,voice,name){const takes=line.voiceTakes??=[],same=takes.find(t=>t.src===voice.src);if(same)return same;if(takes.length>=8)throw Error('Keep up to eight takes per line. Remove a take before saving another.');const take={id:uid(),name:name.trim().slice(0,80)||'Take '+(takes.length+1),src:voice.src,sourceDuration:voice.buffer?.duration||voice.sourceDuration,request:structuredClone(voice.request)};if(!validVoiceTake(take))throw Error('This preview is not a valid voice take.');takes.push(take);return take}
async function auditionVoiceTake(take){if(offlineVoiceBusy)return;try{voiceTakeContext();$('offlineVoiceAudio').pause();$('offlineVoiceAudio').src=take.src;$('offlineVoiceAudio').hidden=false;voiceTakePreviewId=take.id;await $('offlineVoiceAudio').play();$('offlineVoiceStatus').textContent='Auditioning '+take.name+'. The dialogue voice is unchanged.'}catch(e){$('offlineVoiceStatus').textContent=e.message}}
async function chooseVoiceTake(take){if(offlineVoiceBusy)return;try{const {line}=voiceTakeContext(),actor=current().objects.find(o=>o.id===line.speakerId);if(actor?.locked||ownedStoryVoice(line)?.locked)throw Error('Unlock the character and current voice first.');if(!offlineVoices.some(v=>v.id===take.request.voice))throw Error('This take can be auditioned, but its voice profile is not installed.');const buffer=await decodeFile(await(await fetch(take.src)).blob());offlineVoiceCache={key:JSON.stringify(take.request),request:structuredClone(take.request),src:take.src,buffer};$('offlineVoiceText').value=take.request.text;$('offlineVoiceChoice').value=take.request.voice;$('offlineVoiceSpeed').value=String(take.request.speed);if(!$('offlineVoiceSpeed').value){const option=document.createElement('option');option.value=String(take.request.speed);option.textContent='Saved pace · '+take.request.speed;$('offlineVoiceSpeed').append(option);$('offlineVoiceSpeed').value=option.value}$('offlineVoiceDelivery').value=take.request.delivery;await $('addOfflineVoice').onclick()}catch(e){$('offlineVoiceStatus').textContent=e.message}}
function renderVoiceTakes(){const c=offlineVoiceContext,list=$('voiceTakeList');list.replaceChildren();if(!c||project!==c.project)return;const active=tracks().find(a=>a.id===c.line.audioId);for(const take of c.line.voiceTakes||[]){const row=document.createElement('article');row.className='ease-entry';const name=document.createElement('span');name.textContent=take.name+' · '+take.sourceDuration.toFixed(1)+'s'+(active?.src===take.src?' · in dialogue':'')+(take.request.text!==c.line.text?' · earlier text':'');row.append(name,storyButton('Listen',()=>auditionVoiceTake(take)),storyButton('Use take',()=>chooseVoiceTake(take)),storyButton('Remove',()=>{if(offlineVoiceBusy)return;c.line.voiceTakes=c.line.voiceTakes.filter(t=>t!==take);if(c.line.activeVoiceTakeId===take.id)delete c.line.activeVoiceTakeId;save();renderVoiceTakes()}));list.append(row)}if(!list.children.length)list.innerHTML='<p class="note">No saved takes yet. Preview a voice, then save it here.</p>'}
$('saveVoiceTake').onclick=()=>{try{const {line}=voiceTakeContext();if(offlineVoiceBusy)throw Error('Wait for voice processing to finish.');if(!offlineVoiceCache)throw Error('Preview a voice first.');if(offlineVoiceCache.key!==JSON.stringify(offlineVoiceRequest()))throw Error('The settings changed. Preview the new voice before saving it.');rememberVoiceTake(line,offlineVoiceCache,$('voiceTakeName').value);$('voiceTakeName').value='';save();renderVoiceTakes();$('offlineVoiceStatus').textContent='Take saved with the project. Listen and compare before choosing.'}catch(e){$('offlineVoiceStatus').textContent=e.message}};
const openVoiceBeforeTakes=openOfflineVoice;openOfflineVoice=async function(line){voiceTakePreviewId=null;$('voiceTakeName').value='';await openVoiceBeforeTakes(line);renderVoiceTakes()};
const addVoiceBeforeTakes=$('addOfflineVoice').onclick;$('addOfflineVoice').onclick=async()=>{const context=offlineVoiceContext;if(offlineVoiceBusy)return;let previous;try{const c=voiceTakeContext(),clip=ownedStoryVoice(c.line);if(clip?.tts&&/^data:audio\/(?:wav|wave|x-wav);base64,/.test(clip.src))previous={src:clip.src,sourceDuration:clip.sourceDuration,request:{text:c.line.text,voice:clip.tts.voice,speed:clip.tts.speed||1,delivery:clip.tts.delivery||'natural'}};const list=c.line.voiceTakes||[],newSource=offlineVoiceCache?.src;if(list.length>=8&&previous&&!list.some(t=>t.src===previous.src)&&newSource!==previous.src)throw Error('Save or remove a take before replacing this voice; eight takes are already stored.')}catch(e){$('offlineVoiceStatus').textContent=e.message;return}await addVoiceBeforeTakes();if(context===offlineVoiceContext&&project===context.project){const clip=tracks().find(a=>a.id===context.line.audioId);if(clip&&offlineVoiceCache?.src===clip.src){if(previous&&previous.src!==clip.src)try{rememberVoiceTake(context.line,previous,'Previous dialogue voice')}catch{}const saved=context.line.voiceTakes?.find(t=>t.src===clip.src);context.line.activeVoiceTakeId=saved?.id||undefined;save();renderVoiceTakes()}}};
const validBeforeVoiceTakes=valid;valid=function(p){try{return validBeforeVoiceTakes(p)&&p.scenes.every(s=>storyLines(s).every(l=>(!l.voiceTakes||Array.isArray(l.voiceTakes)&&l.voiceTakes.length<=8&&new Set(l.voiceTakes.map(t=>t.id)).size===l.voiceTakes.length&&l.voiceTakes.every(validVoiceTake))&&(!l.activeVoiceTakeId||typeof l.activeVoiceTakeId==='string'&&l.voiceTakes?.some(t=>t.id===l.activeVoiceTakeId))))}catch{return false}};
